payload.template:
module seq1101 (
  input  logic clk,
  input  logic rst,
  input  logic din,
  output logic found
);

  // your code here.
  //
  // Suggested shape: a state register holding how much of the pattern
  // has been seen, a next-state decision, and a registered found.
  //
  // The transition to get right is what happens after a match: the
  // last bit of 1101 is a 1, and a 1 is the start of the next 1101.

endmodule

payload.testbench:
`timescale 1ns/1ps
// The sample testbench. Run uses this one; Submit uses a different
// one that tries cases this does not.
module tb;
  logic clk = 1'b0, rst = 1'b1, din = 1'b0, found;
  int hits = 0;

  seq1101 dut (.clk(clk), .rst(rst), .din(din), .found(found));

  always #5 clk = ~clk;
  always @(negedge clk) if (found) hits++;

  // Drive one bit per cycle, most significant first.
  task automatic feed(input logic [31:0] bits, input int n);
    for (int i = n - 1; i >= 0; i--) begin
      @(negedge clk) din = bits[i];
      @(posedge clk);
    end
  endtask

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    @(posedge clk); @(negedge clk);
    $display("CHECK after_reset 0 %b AT %0d", found, $time);
    rst = 1'b0;

    // One clean match.
    feed(32'b1101, 4);
    @(negedge clk); #1;
    $display("CHECK one_match 1 %0d AT %0d", hits, $time);

    // Nothing in a pattern that never completes.
    feed(32'b1001001, 7);
    @(negedge clk); #1;
    $display("CHECK no_false_positive 1 %0d AT %0d", hits, $time);

    repeat (2) @(posedge clk);
    @(negedge clk); #1;
    $display("CHECK stays 1 %0d AT %0d", hits, $time);
    $display("DONE 4");
    $finish;
  end
endmodule
